  // One shared geographic transform for outlines and facility centers.
  // No prefecture bounding boxes, per-facility offsets or marker relaxation.
  const PROJECTION = Object.freeze({"scale":29.632068907186063,"xOrigin":12.20031896989633,"yOrigin":1629.0557505770232,"longitudeOrigin":122});
  function project(longitude, latitude) {
    if (!Number.isFinite(longitude) || !Number.isFinite(latitude) || Math.abs(latitude)>=85) return null;
    const y=Math.log(Math.tan(Math.PI/4+latitude*Math.PI/360))*180/Math.PI;
    return [PROJECTION.xOrigin+(longitude-PROJECTION.longitudeOrigin)*PROJECTION.scale, PROJECTION.yOrigin-y*PROJECTION.scale];
  }
  const VERIFIED_ONSEN_POSITIONS = {};

  function getStatus(total, visitedCount) {
    if (total === 0) {
      return { status: 'empty', label: '登録施設なし', pct: null };
    }
    if (visitedCount === 0) {
      return { status: 'zero', label: '0%（0 / ' + total + ' 施設）', pct: 0 };
    }
    const pct = Math.round((100 * visitedCount) / total);
    if (pct < 50) {
      return { status: 'low', label: pct + '%（' + visitedCount + ' / ' + total + ' 施設）', pct: pct };
    }
    if (pct < 100) {
      return { status: 'mid', label: pct + '%（' + visitedCount + ' / ' + total + ' 施設）', pct: pct };
    }
    return { status: 'complete', label: '100%（' + visitedCount + ' / ' + total + ' 施設達成）', pct: 100 };
  }

  function getPrefStats(prefName, data, isVisited) {
    const facilities = data.filter(function(x) { return x.prefecture === prefName; });
    const total = facilities.length;
    const visitedCount = facilities.filter(isVisited).length;
    const statusObj = getStatus(total, visitedCount);
    return {
      name: prefName,
      total: total,
      visitedCount: visitedCount,
      pct: statusObj.pct,
      status: statusObj.status,
      statusLabel: statusObj.label
    };
  }

  function createViewport() {
    let zoom=1,x=0,y=0;
    const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
    function set(nextZoom,nextX,nextY) {
      zoom=clamp(nextZoom,1,8);const size=1000/zoom;
      x=clamp(nextX,0,1000-size);y=clamp(nextY,0,1000-size);
      return get();
    }
    function get(){return {zoom:zoom,x:x,y:y,size:1000/zoom};}
    return {get:get,set:set,reset:()=>set(1,0,0),
      zoomAt:function(next,rx=.5,ry=.5){const old=get(),z=clamp(next,1,8),size=1000/z;return set(z,old.x+rx*old.size-rx*size,old.y+ry*old.size-ry*size);},
      pan:function(dx,dy){return set(zoom,x+dx,y+dy);},
      region:function(){const nw=project(137.7,41.8),se=project(143.1,35);const size=Math.max(se[0]-nw[0],se[1]-nw[1])+40,z=clamp(1000/size,1,8);return set(z,(nw[0]+se[0])/2-500/z,(nw[1]+se[1])/2-500/z);}
    };
  }

